+func electsWithin(t *testing.T, cluster *memoryCluster, ticks int) bool {
+	t.Helper()
+	for range ticks {
+		for _, id := range []uint32{2, 3} {
+			cluster.enqueueReady(t, id, cluster.tick(t, id))
+		}
+		cluster.drain(t, 100)
+		for _, id := range []uint32{2, 3} {
+			if cluster.nodes[id].Snapshot().Role == Leader {
+				return true
+			}
+		}
+	}
+	return false
