+func TestSkippedIndexRewritesLeaveAValidIndexAfterRestart(t *testing.T) {
+	t.Parallel()
+	root, _ := formatM1DataDir(t)
+	partition := openIndexTestPartition(t, root, adapters.OSFileSystem{})
+	for sequence := uint64(1); sequence <= 20; sequence++ {
